/**
 * Standalone SearchOverlay Implementation
 * Production-ready search functionality with robust error handling
 */

// Self-contained, immediately invoked function to avoid conflicts
(function() {
  'use strict';

  console.log('🔍 Starting standalone SearchOverlay initialization...');

  // Check if SearchOverlay already exists to prevent duplicates
  if (window.SearchOverlay && window.searchOverlay) {
    console.log('SearchOverlay already initialized, skipping...');
    return;
  }

  class SearchOverlay {
    constructor() {
      console.log('SearchOverlay constructor called');
      this.overlay = null;
      this.searchInput = null;
      this.searchResults = null;
      this.isOpen = false;
      this.searchData = [];
      this.fuse = null;
      this.initialized = false;
      
      // Bind methods to maintain context
      this.open = this.open.bind(this);
      this.close = this.close.bind(this);
      this.handleKeydown = this.handleKeydown.bind(this);
      
      this.init();
    }

    async init() {
      try {
        // Wait for DOM if needed
        if (document.readyState === 'loading') {
          return new Promise(resolve => {
            document.addEventListener('DOMContentLoaded', () => {
              this.init().then(resolve);
            });
          });
        }

        // Get DOM elements
        this.overlay = document.getElementById('search-overlay');
        this.searchInput = document.getElementById('search-input');
        this.searchResults = document.getElementById('search-results');

        if (!this.overlay || !this.searchInput || !this.searchResults) {
          console.warn('SearchOverlay: DOM elements not found, retrying in 500ms...');
          setTimeout(() => this.init(), 500);
          return;
        }

        console.log('SearchOverlay: DOM elements found, initializing...');

        // Load dependencies and set up functionality
        await this.loadSearchData();
        await this.loadFuseJS();
        this.setupFuzzySearch();
        this.bindEvents();
        this.setupKeyboardShortcuts();
        
        this.initialized = true;
        console.log('✅ SearchOverlay initialized successfully!');
        
        // Dispatch ready event
        document.dispatchEvent(new CustomEvent('searchOverlayReady', {
          detail: { instance: this }
        }));
        
      } catch (error) {
        console.error('SearchOverlay initialization failed:', error);
        // Retry once after a delay
        setTimeout(() => this.init(), 1000);
      }
    }

    async loadSearchData() {
      try {
        // Simplified data for immediate functionality
        this.searchData = [
          {
            type: 'page',
            title: 'Home',
            description: 'Blake Oxford - Systems Architect and Developer Portfolio',
            url: '/',
            tags: ['home', 'portfolio', 'developer'],
            date: null
          },
          {
            type: 'page',
            title: 'About',
            description: 'Learn about Blake Oxford, Systems Architect and Developer',
            url: '/about',
            tags: ['about', 'bio', 'experience'],
            date: null
          },
          {
            type: 'page',
            title: 'Projects',
            description: 'Portfolio of development projects and achievements',
            url: '/projects',
            tags: ['projects', 'portfolio', 'development'],
            date: null
          },
          {
            type: 'page',
            title: 'Blog',
            description: 'Technical articles and insights',
            url: '/blog',
            tags: ['blog', 'articles', 'technical'],
            date: null
          },
          {
            type: 'page',
            title: 'Contact',
            description: 'Get in touch with Blake Oxford',
            url: '/contact',
            tags: ['contact', 'email', 'message'],
            date: null
          }
        ];

        // Try to load dynamic data without causing errors
        try {
          const [blogResponse, projectsResponse] = await Promise.allSettled([
            fetch('/api/blog.json').catch(() => ({ ok: false })),
            fetch('/api/projects.json').catch(() => ({ ok: false }))
          ]);
          
          if (blogResponse.status === 'fulfilled' && blogResponse.value.ok) {
            const blogData = await blogResponse.value.json();
            this.searchData.push(...blogData.map(post => ({
              type: 'blog',
              title: post.title,
              description: post.description || '',
              url: `/blog/${post.slug}`,
              tags: post.tags || [],
              date: post.publishedAt
            })));
          }
          
          if (projectsResponse.status === 'fulfilled' && projectsResponse.value.ok) {
            const projectsData = await projectsResponse.value.json();
            this.searchData.push(...projectsData.map(project => ({
              type: 'project',
              title: project.title,
              description: project.description || '',
              url: `/projects/${project.slug}`,
              tags: project.tags || [],
              date: project.publishedAt
            })));
          }
        } catch (error) {
          console.warn('SearchOverlay: Could not load dynamic data, using static data');
        }
        
        console.log(`SearchOverlay: Loaded ${this.searchData.length} search items`);
      } catch (error) {
        console.error('Failed to load search data:', error);
        this.searchData = [];
      }
    }

    async loadFuseJS() {
      if (typeof Fuse !== 'undefined') {
        return Promise.resolve();
      }

      return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/npm/fuse.js@7.0.0/dist/fuse.min.js';
        script.async = true;
        
        script.onload = () => {
          console.log('Fuse.js loaded successfully');
          resolve();
        };
        
        script.onerror = () => {
          console.warn('Failed to load Fuse.js, using basic search');
          resolve(); // Don't reject, fall back to basic search
        };
        
        document.head.appendChild(script);
      });
    }

    setupFuzzySearch() {
      if (typeof Fuse === 'undefined') {
        console.warn('Fuse.js not loaded, using basic search');
        return;
      }

      const options = {
        keys: [
          { name: 'title', weight: 0.4 },
          { name: 'description', weight: 0.3 },
          { name: 'tags', weight: 0.3 }
        ],
        threshold: 0.4,
        distance: 100,
        includeScore: true,
        minMatchCharLength: 2
      };

      this.fuse = new Fuse(this.searchData, options);
    }

    bindEvents() {
      // Search toggle button
      const searchToggle = document.getElementById('search-toggle');
      if (searchToggle) {
        searchToggle.addEventListener('click', (e) => {
          e.preventDefault();
          this.open();
        });
      }

      // Close button
      const closeButton = document.getElementById('close-search');
      if (closeButton) {
        closeButton.addEventListener('click', () => this.close());
      }

      // Backdrop click
      if (this.overlay) {
        this.overlay.addEventListener('click', (e) => {
          if (e.target === this.overlay) {
            this.close();
          }
        });
      }

      // Search input
      if (this.searchInput) {
        this.searchInput.addEventListener('input', (e) => {
          this.handleSearch(e.target.value);
        });

        this.searchInput.addEventListener('keydown', (e) => {
          this.handleKeyNavigation(e);
        });
      }

      // Escape key
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && this.isOpen) {
          this.close();
        }
      });
    }

    setupKeyboardShortcuts() {
      console.log('Setting up keyboard shortcuts');
      document.addEventListener('keydown', this.handleKeydown);
    }

    handleKeydown(e) {
      // Ctrl+K or Cmd+K to open search
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        console.log('Control+K detected, opening search overlay');
        e.preventDefault();
        this.open();
        return;
      }

      // Forward slash to open search (if not in input)
      if (e.key === '/' && !this.isInputFocused()) {
        console.log('/ key detected, opening search overlay');
        e.preventDefault();
        this.open();
        return;
      }
    }

    isInputFocused() {
      const activeElement = document.activeElement;
      return activeElement && (
        activeElement.tagName === 'INPUT' ||
        activeElement.tagName === 'TEXTAREA' ||
        activeElement.contentEditable === 'true'
      );
    }

    open() {
      console.log('SearchOverlay.open() called');
      if (!this.overlay) {
        console.error('Search overlay element not found');
        return;
      }

      console.log('Opening search overlay');
      this.isOpen = true;
      this.overlay.classList.add('active');
      document.body.style.overflow = 'hidden';

      // Focus search input with multiple attempts for reliability
      const focusInput = () => {
        if (this.searchInput) {
          this.searchInput.focus();
          this.searchInput.select();

          // Verify focus worked
          setTimeout(() => {
            if (document.activeElement !== this.searchInput) {
              this.searchInput.focus();
            }
          }, 50);
        }
      };

      setTimeout(focusInput, 100);
      setTimeout(focusInput, 300);

      // Update ARIA
      if (this.searchInput) {
        this.searchInput.setAttribute('aria-expanded', 'true');
      }
    }

    close() {
      if (!this.overlay) return;

      this.isOpen = false;
      this.overlay.classList.remove('active');
      document.body.style.overflow = '';

      // Clear search
      if (this.searchInput) {
        this.searchInput.value = '';
        this.searchInput.setAttribute('aria-expanded', 'false');
      }
      this.clearResults();
    }

    handleSearch(query) {
      if (!query.trim()) {
        this.clearResults();
        return;
      }

      const results = this.performSearch(query);
      this.displayResults(results, query);
    }

    performSearch(query) {
      if (this.fuse) {
        const fuseResults = this.fuse.search(query);
        return fuseResults.map(result => ({
          ...result.item,
          score: result.score
        }));
      } else {
        // Fallback to basic search
        const lowerQuery = query.toLowerCase();
        return this.searchData.filter(item => 
          item.title.toLowerCase().includes(lowerQuery) ||
          item.description.toLowerCase().includes(lowerQuery) ||
          item.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
        );
      }
    }

    displayResults(results, query) {
      if (!this.searchResults) return;

      if (results.length === 0) {
        this.searchResults.innerHTML = `
          <div class="p-4 text-center text-gray-500">
            No results found for "${query}"
          </div>
        `;
        this.searchResults.style.display = 'block';
        return;
      }

      const resultHTML = results.slice(0, 8).map((item, index) => `
        <a 
          href="${item.url}" 
          class="search-result-item block p-3 hover:bg-gray-50 dark:hover:bg-gray-800 border-b border-gray-100 dark:border-gray-700 last:border-b-0"
          data-index="${index}"
          role="option"
          aria-selected="false"
        >
          <div class="flex items-start gap-3">
            <div class="search-result-icon flex-shrink-0 w-6 h-6 mt-1">
              ${this.getTypeIcon(item.type)}
            </div>
            <div class="flex-1 min-w-0">
              <div class="search-result-title font-medium text-gray-900 dark:text-gray-100 truncate">
                ${this.highlightQuery(item.title, query)}
              </div>
              ${item.description ? `
                <div class="search-result-description text-sm text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                  ${this.highlightQuery(item.description, query)}
                </div>
              ` : ''}
              <div class="search-result-meta flex items-center gap-2 mt-2 text-xs text-gray-500 dark:text-gray-500">
                <span class="search-result-type capitalize">${item.type}</span>
                ${item.date ? `<span>•</span><span>${new Date(item.date).toLocaleDateString()}</span>` : ''}
              </div>
            </div>
          </div>
        </a>
      `).join('');

      this.searchResults.innerHTML = resultHTML;
      this.searchResults.style.display = 'block';

      // Update ARIA
      this.searchResults.setAttribute('aria-label', `${results.length} search results for ${query}`);
    }

    getTypeIcon(type) {
      const icons = {
        blog: '<svg class="w-5 h-5 text-blue-500" fill="currentColor" viewBox="0 0 24 24"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>',
        project: '<svg class="w-5 h-5 text-green-500" fill="currentColor" viewBox="0 0 24 24"><path d="M20 6h-2.18c.11-.31.18-.65.18-1a2.996 2.996 0 0 0-5.5-1.65l-.5.67-.5-.68C10.96 2.54 10.05 2 9 2 7.34 2 6 3.34 6 5c0 .35.07.69.18 1H4c-1.11 0-2 .89-2 2v11c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V8c0-1.11-.89-2-2-2z"/></svg>',
        page: '<svg class="w-5 h-5 text-purple-500" fill="currentColor" viewBox="0 0 24 24"><path d="M14,2H6A2,2 0 0,0 4,4V20A2,2 0 0,0 6,22H18A2,2 0 0,0 20,20V8L14,2M18,20H6V4H13V9H18V20Z"/></svg>'
      };
      return icons[type] || icons.page;
    }

    highlightQuery(text, query) {
      if (!query.trim()) return text;

      const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
      return text.replace(regex, '<mark class="bg-yellow-200 dark:bg-yellow-800 px-1 rounded">$1</mark>');
    }

    handleKeyNavigation(e) {
      const results = this.searchResults?.querySelectorAll('.search-result-item');
      if (!results || results.length === 0) return;

      const currentSelected = this.searchResults.querySelector('[aria-selected="true"]');
      let currentIndex = currentSelected ? parseInt(currentSelected.dataset.index) : -1;

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          currentIndex = Math.min(currentIndex + 1, results.length - 1);
          this.updateSelection(results, currentIndex);
          break;
        case 'ArrowUp':
          e.preventDefault();
          currentIndex = Math.max(currentIndex - 1, 0);
          this.updateSelection(results, currentIndex);
          break;
        case 'Enter':
          e.preventDefault();
          if (currentSelected) {
            currentSelected.click();
          }
          break;
      }
    }

    updateSelection(results, index) {
      // Clear previous selection
      results.forEach(result => result.setAttribute('aria-selected', 'false'));
      
      // Set new selection
      if (results[index]) {
        results[index].setAttribute('aria-selected', 'true');
        results[index].scrollIntoView({ block: 'nearest' });
      }
    }

    clearResults() {
      if (this.searchResults) {
        this.searchResults.innerHTML = '';
        this.searchResults.style.display = 'none';
      }
    }
  }

  // Expose SearchOverlay globally
  window.SearchOverlay = SearchOverlay;

  // Initialize when ready
  function initializeSearchOverlay() {
    console.log('🔍 Initializing SearchOverlay...');
    
    try {
      if (window.searchOverlay) {
        console.log('SearchOverlay already exists, skipping creation');
        return;
      }
      
      console.log('Creating new SearchOverlay instance');
      window.searchOverlay = new SearchOverlay();
      console.log('✅ SearchOverlay instance created successfully');
      
    } catch (error) {
      console.error('❌ Failed to create SearchOverlay:', error);
    }
  }
  
  // Initialize based on document state
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeSearchOverlay);
  } else {
    // DOM already loaded
    initializeSearchOverlay();
  }

})();
